def find_sequences(max_val=10):
    # Try to find sequences a[0], a[1], ... such that a[a[a[p]]] = a[p+1] + 1
    # Since we don't know the range of a[p], let's try a[p] = p + c
    # or a[p] = some other linear form.

    for c in range(-5, 10):
        a = lambda n: n + c
        valid = True
        for p in range(10):
            if a(a(a(p))) != a(p+1) + 1:
                valid = False
                break
        if valid:
            print(f"Found a[n] = n + {c}")

